1610	+/// A queued SSE response is delivered as the exact [chunks] given, each
1611	+/// its own separate stream emission (never pre-joined into one string) —
1612	+/// this is what proves `ChatRemoteDataSource.sendMessage`'s own
1613	+/// `\n\n`-boundary buffering really works across genuine network chunk
1614	+/// boundaries, not just against a single already-complete event.
1615	+class _FakeHttpClientAdapter implements HttpClientAdapter {
1616	+  final List<RequestOptions> requests = [];
1617	+  final List<ResponseBody Function()> _queue = [];
1618	+
1619	+  void queueJsonResponse(int statusCode, Map<String, dynamic> body) {
1620	+    _queue.add(
1621	+      () => ResponseBody.fromString(
1622	+        jsonEncode(body),
1623	+        statusCode,
1624	+        headers: {
1625	+          Headers.contentTypeHeader: [Headers.jsonContentType],
1626	+        },
1627	+      ),
1628	+    );
1629	+  }
