1634	+      'message': message,
1635	+      'retryable': true,
1636	+    });
1637	+  }
1638	+
1639	+  void queueSseResponse(List<String> chunks, {int statusCode = 200}) {
1640	+    _queue.add(
1641	+      () => ResponseBody(
1642	+        Stream.fromIterable(
1643	+          chunks.map((chunk) => Uint8List.fromList(utf8.encode(chunk))),
1644	+        ),
1645	+        statusCode,
1646	+        headers: {
1647	+          Headers.contentTypeHeader: ['text/event-stream'],
1648	+        },
1649	+      ),
1650	+    );
1651	+  }
