      expect(
        dataSource.sendMessage('s1', 'hello'),
        emitsInOrder([
          isA<Right<Failure, ChatStreamEvent>>().having(
            (r) => r.getRight().toNullable(),
            'event',
            isA<ChatDoneEvent>(),
          ),
          emitsDone,
        ]),
      );
    });
